input.oldString:
$('autoBtn').addEventListener('click', () => {
  if (state.auto) { stopAuto(); toast('Giro automático pausado.'); return; }
  if (state.spinning) return;
  state.auto = true; state.autoLeft = 10; $('autoBtn').classList.add('active'); $('autoBtn').textContent = '■ Parar automático'; spin();
});

